-- PsyLab V62 — La Blouse : banque de 12 dossiers + scoring clinique multidimensionnel
-- À exécuter après les migrations précédentes (V51/V54/V60).
-- Les vignettes sont originales et synthétiques ; les références pédagogiques sont stockées dans le contenu sans reproduire de texte source.

insert into public.challenge_templates(template_id,course_key,content,answer_key,max_score) values
(1,'bipolar','{"fr":{"title":"L’épisode oublié","subtitle":"Une dépression actuelle ne raconte pas toute l’histoire.","intro":"Une dépression actuelle ne raconte pas toute l’histoire.","hypotheses":["Trouble dépressif majeur","Trouble bipolaire II","Trouble bipolaire I","Trouble de l’adaptation"],"steps":[{"kind":"single","label":"Première impression","prompt":"Une patiente de 29 ans consulte pour un épisode dépressif caractérisé. Aucun épisode maniaque n’est rapporté spontanément. Quelle attitude est la plus rigoureuse ?","competency":"n2.branching","choices":["Retenir d’emblée un trouble dépressif majeur","Rechercher systématiquement des périodes antérieures d’activation","Conclure à un trouble bipolaire II"],"ask_leader":true,"debrief":"Une dépression actuelle ne permet pas, à elle seule, d’exclure une bipolarité antérieure. La reconstruction longitudinale est donc prioritaire.","discriminant":"Existence d’une période antérieure distincte d’activation.","trap":"La plainte actuelle pousse naturellement vers un raisonnement transversal centré sur la dépression."},{"kind":"multi","label":"Enquête","prompt":"Vous ne pouvez approfondir que deux éléments avant de poursuivre. Lesquels sont les plus discriminants ?","competency":"n2.evidence","choices":["Périodes antérieures avec réduction du besoin de sommeil et augmentation d’énergie","Variations de poids au cours des cinq dernières années","Changements observables du fonctionnement lors de périodes d’activation","Préférence pour le travail nocturne"],"required":2,"max":2,"debrief":"Réduction du besoin de sommeil et changement observable du fonctionnement ont une valeur discriminante supérieure aux détails non spécifiques.","discriminant":"Besoin de sommeil + changement du baseline.","trap":"Les données biographiques accessoires paraissent concrètes mais discriminent peu."},{"kind":"single","label":"Nouvelle donnée","prompt":"Sa sœur décrit, deux ans plus tôt, cinq jours durant lesquels la patiente dormait peu, menait plusieurs projets simultanément et était nettement plus expansive, sans retentissement majeur.","competency":"n2.evidence","choices":"Quelle conséquence cette donnée a-t-elle sur l’arbre diagnostique ?","reveal":["Elle renforce nettement l’hypothèse de bipolarité","Elle confirme une manie","Elle est sans valeur car rapportée par un proche"],"ask_leader":true,"debrief":"Une information collatérale cohérente peut faire remonter fortement une hypomanie passée, surtout si le patient ne l’avait pas identifiée comme pathologique.","discriminant":"Période distincte de cinq jours avec activation observable.","trap":"On peut sous-estimer un témoignage collatéral parce qu’il ne vient pas directement du patient."},{"kind":"single","label":"Vous maintenez ?","prompt":"La patiente n’a jamais présenté de symptômes psychotiques ni d’altération marquée du fonctionnement pendant ces périodes.","competency":"n2.revision","choices":"Quelle révision est la plus appropriée ?","reveal":["Privilégier un trouble bipolaire II si l’épisode hypomaniaque est suffisamment caractérisé","Revenir au trouble dépressif majeur car il n’y a pas de psychose","Conclure à un trouble bipolaire I"],"ask_leader":true,"debrief":"L’absence de psychose ou de retentissement majeur n’annule pas l’hypomanie ; elle contribue au contraire à la distinguer de la manie.","discriminant":"Activation syndromique sans sévérité maniaque.","trap":"Assimiler absence de psychose à absence de bipolarité est un raccourci."},{"kind":"single","label":"Argument décisif","prompt":"Quel élément est ici le plus discriminant ?","competency":"n2.discrimination","choices":["La dépression actuelle","L’existence d’une période distincte d’activation avec changement observable du fonctionnement","L’âge de 29 ans"],"debrief":"Le diagnostic longitudinal bascule sur l’existence d’un épisode hypomaniaque suffisamment caractérisé, pas sur la dépression présente.","discriminant":"Antécédent hypomaniaque distinct.","trap":"La dépression est saillante mais non discriminante entre unipolaire et bipolaire II."},{"kind":"final","label":"Signature","prompt":"Signez le dossier avec l’hypothèse la mieux soutenue.","competency":"n2.formulation","diagnosis_choices":["Trouble dépressif majeur","Trouble bipolaire II","Trouble bipolaire I","Trouble de l’adaptation"],"argument_choices":["Dépression actuelle","Antécédent d’épisode hypomaniaque suffisamment caractérisé","Absence de psychose"],"debrief":"L’association d’un épisode dépressif majeur et d’un épisode hypomaniaque suffisamment caractérisé, sans manie, soutient le cadre bipolaire II.","discriminant":"Architecture longitudinale dépression + hypomanie.","trap":"Signer uniquement à partir de l’état actuel efface l’histoire de la maladie."}],"references":["DSM-5-TR — Troubles bipolaires et apparentés","Jansson & Nordgaard — The Psychiatric Interview"]},"en":{"title":"The forgotten episode","subtitle":"A current depression does not tell the whole story.","intro":"A current depression does not tell the whole story.","hypotheses":["Major depressive disorder","Bipolar II disorder","Bipolar I disorder","Adjustment disorder"],"steps":[{"kind":"single","label":"First impression","prompt":"A 29-year-old patient presents with a major depressive episode. No manic episode is spontaneously reported. What is the most rigorous approach?","competency":"n2.branching","choices":["Immediately diagnose major depressive disorder","Systematically probe for past periods of activation","Diagnose bipolar II disorder now"],"ask_leader":true},{"kind":"multi","label":"Inquiry","prompt":"You can explore only two elements before proceeding. Which are most discriminating?","competency":"n2.evidence","choices":["Past periods of reduced need for sleep with increased energy","Weight changes over the last five years","Observable functional change during activation periods","Preference for night work"],"required":2,"max":2},{"kind":"single","label":"New information","prompt":"Her sister describes a five-day period two years earlier with little sleep, multiple simultaneous projects and clear expansiveness, without marked impairment.","competency":"n2.evidence","choices":"How should this information change the diagnostic tree?","reveal":["It substantially strengthens bipolarity","It confirms mania","It has no value because it is collateral information"],"ask_leader":true},{"kind":"single","label":"Do you maintain?","prompt":"She has never had psychotic symptoms or marked functional impairment during those periods.","competency":"n2.revision","choices":"What revision is most appropriate?","reveal":["Favor bipolar II if the hypomanic episode is sufficiently characterized","Return to major depressive disorder because there was no psychosis","Diagnose bipolar I disorder"],"ask_leader":true},{"kind":"single","label":"Decisive argument","prompt":"Which element is most discriminating here?","competency":"n2.discrimination","choices":["The current depression","A distinct activation period with observable functional change","Age 29"]},{"kind":"final","label":"Signature","prompt":"Sign the case with the best-supported hypothesis.","competency":"n2.formulation","diagnosis_choices":["Major depressive disorder","Bipolar II disorder","Bipolar I disorder","Adjustment disorder"],"argument_choices":["Current depression","A sufficiently characterized past hypomanic episode","Absence of psychosis"]}],"references":["DSM-5-TR — Troubles bipolaires et apparentés","Jansson & Nordgaard — The Psychiatric Interview"]}}'::jsonb,'{"steps":[{"kind":"single","correct":1,"certainty_target":70,"leader_correct":[0,1]},{"kind":"multi","correct":[0,2],"certainty_target":80},{"kind":"single","correct":0,"certainty_target":85,"leader_correct":[1]},{"kind":"single","correct":0,"certainty_target":90,"leader_correct":[1],"revision":"maintain"},{"kind":"single","correct":1},{"kind":"final","diagnosis":1,"argument":1,"certainty_target":90}]}'::jsonb,100),
(2,'bipolar','{"fr":{"title":"Le détail qui change tout","subtitle":"Dormir peu n’est pas forcément avoir moins besoin de dormir.","intro":"Dormir peu n’est pas forcément avoir moins besoin de dormir.","hypotheses":["Insomnie anxieuse","Épisode d’activation thymique","Restriction volontaire de sommeil","Trouble du rythme veille-sommeil"],"steps":[{"kind":"single","label":"Première impression","prompt":"Un patient dort environ quatre heures par nuit depuis huit jours, se réveille spontanément et dit se sentir « parfaitement reposé ». Quelle donnée mérite le plus de poids ?","competency":"n1.sleep","choices":["Le nombre absolu de quatre heures","L’absence de besoin de dormir davantage malgré le sommeil réduit","Le fait qu’il se couche tard"],"ask_leader":true,"debrief":"Dormir peu n’est pas synonyme de diminution du besoin de sommeil. L’absence de fatigue et de désir de récupérer change la signification du symptôme.","discriminant":"Besoin subjectif de sommeil, non durée brute.","trap":"Le nombre d’heures attire l’attention parce qu’il est facile à quantifier."},{"kind":"multi","label":"Enquête","prompt":"Quelles deux questions discriminent le mieux une diminution du besoin de sommeil d’une insomnie ?","competency":"n2.evidence","choices":["Souhaitez-vous dormir davantage mais n’y arrivez-vous pas ?","Ressentez-vous fatigue ou besoin de récupération dans la journée ?","À quelle heure prenez-vous votre dîner ?","Avez-vous toujours préféré les matelas fermes ?"],"required":2,"max":2,"debrief":"Les questions discriminantes portent sur le désir de dormir davantage et les conséquences du manque.","discriminant":"Fatigue/compensation et désir de sommeil.","trap":"Des détails d’hygiène de vie peuvent être pertinents mais ne tranchent pas la distinction sémiologique."},{"kind":"single","label":"Nouvelle donnée","prompt":"Il ajoute qu’il travaille davantage, parle plus vite et a lancé plusieurs projets en même temps.","competency":"n2.evidence","choices":"Quelle interprétation devient la plus solide ?","reveal":["Simple insomnie isolée","Activation thymique syndromique à caractériser","Restriction volontaire sans valeur psychopathologique"],"ask_leader":true,"debrief":"L’association à une activation globale rend l’hypothèse thymique plus cohérente qu’une insomnie isolée.","discriminant":"Sommeil réduit + énergie/projets/parole.","trap":"L’insomnie reste plausible si l’on isole le sommeil du reste du syndrome."},{"kind":"single","label":"Vous maintenez ?","prompt":"Le fonctionnement professionnel reste globalement préservé et aucun symptôme psychotique n’est retrouvé.","competency":"n2.revision","choices":"Que faut-il conclure à ce stade ?","reveal":["Une hypomanie est possible si les autres critères et la durée sont réunis","L’absence de psychose exclut toute bipolarité","Il s’agit nécessairement d’une manie"],"ask_leader":true,"debrief":"Une hypomanie reste possible si durée, symptômes et changement fonctionnel sont réunis ; l’absence de psychose n’exclut pas la bipolarité.","discriminant":"Seuil de sévérité et retentissement.","trap":"Confondre absence de psychose et absence de trouble bipolaire est fréquent."},{"kind":"single","label":"Argument décisif","prompt":"Quelle distinction sémiologique est centrale ?","competency":"n2.discrimination","choices":["Sommeil court versus sommeil long","Durée de sommeil versus besoin subjectif de sommeil","Sommeil de semaine versus sommeil de week-end"],"debrief":"La distinction fondamentale est qualitative : durée de sommeil versus besoin de sommeil.","discriminant":"Besoin subjectif de dormir.","trap":"Le chiffre du sommeil peut masquer la phénoménologie."},{"kind":"final","label":"Signature","prompt":"Quelle hypothèse est la mieux soutenue par les données actuelles ?","competency":"n2.formulation","diagnosis_choices":["Insomnie anxieuse","Épisode d’activation thymique","Restriction volontaire de sommeil","Trouble du rythme veille-sommeil"],"argument_choices":["Sommeil inférieur à cinq heures","Réduction du besoin de sommeil associée à une activation globale","Absence de plainte d’endormissement"],"debrief":"Le tableau soutient une activation thymique à caractériser plutôt qu’une simple plainte de sommeil.","discriminant":"Constellation d’activation avec besoin de sommeil diminué.","trap":"Une réponse centrée sur le sommeil seul perd la structure syndromique."}],"references":["DSM-5-TR — Troubles bipolaires et apparentés","Psychiatrie clinique (Lalonde) — Troubles bipolaires"]},"en":{"title":"The detail that changes everything","subtitle":"Sleeping less is not the same as needing less sleep.","intro":"Sleeping less is not the same as needing less sleep.","hypotheses":["Anxiety-related insomnia","Mood activation episode","Voluntary sleep restriction","Sleep-wake rhythm disorder"],"steps":[{"kind":"single","label":"First impression","prompt":"A patient sleeps about four hours nightly for eight days, wakes spontaneously and feels ''perfectly rested.'' Which datum carries the most weight?","competency":"n1.sleep","choices":["The absolute four-hour duration","No desire for more sleep despite shortened sleep","Going to bed late"],"ask_leader":true},{"kind":"multi","label":"Inquiry","prompt":"Which two questions best discriminate reduced need for sleep from insomnia?","competency":"n2.evidence","choices":["Would you like to sleep more but cannot?","Do you feel daytime fatigue or a need to recover?","What time do you eat dinner?","Have you always preferred firm mattresses?"],"required":2,"max":2},{"kind":"single","label":"New information","prompt":"He adds that he is working more, speaking faster and has started several projects at once.","competency":"n2.evidence","choices":"Which interpretation is now strongest?","reveal":["Isolated insomnia","A syndromic mood activation that needs characterization","Voluntary sleep restriction with no psychopathological significance"],"ask_leader":true},{"kind":"single","label":"Do you maintain?","prompt":"Occupational functioning is largely preserved and there are no psychotic symptoms.","competency":"n2.revision","choices":"What can be concluded at this stage?","reveal":["Hypomania is possible if the remaining criteria and duration are met","Absence of psychosis excludes bipolarity","This is necessarily mania"],"ask_leader":true},{"kind":"single","label":"Decisive argument","prompt":"Which phenomenological distinction is central?","competency":"n2.discrimination","choices":["Short sleep versus long sleep","Sleep duration versus subjective need for sleep","Weekday versus weekend sleep"]},{"kind":"final","label":"Signature","prompt":"Which hypothesis is best supported by the current data?","competency":"n2.formulation","diagnosis_choices":["Anxiety-related insomnia","Mood activation episode","Voluntary sleep restriction","Sleep-wake rhythm disorder"],"argument_choices":["Sleeping fewer than five hours","Reduced need for sleep within a broader activation syndrome","No complaint of sleep initiation"]}],"references":["DSM-5-TR — Troubles bipolaires et apparentés","Psychiatrie clinique (Lalonde) — Troubles bipolaires"]}}'::jsonb,'{"steps":[{"kind":"single","correct":1,"certainty_target":85,"leader_correct":[0,1]},{"kind":"multi","correct":[0,1],"certainty_target":90},{"kind":"single","correct":1,"certainty_target":90,"leader_correct":[1]},{"kind":"single","correct":0,"certainty_target":80,"leader_correct":[1],"revision":"maintain"},{"kind":"single","correct":1},{"kind":"final","diagnosis":1,"argument":1,"certainty_target":85}]}'::jsonb,100),
(3,'bipolar','{"fr":{"title":"La chronologie d’abord","subtitle":"Présence n’est pas causalité.","intro":"Présence n’est pas causalité.","hypotheses":["Trouble bipolaire primaire","Trouble de l’humeur induit par substance ou médicament","Anxiété avec agitation","TDAH"],"steps":[{"kind":"single","label":"Première impression","prompt":"Un adulte sans antécédent connu présente depuis une semaine agitation, irritabilité et sommeil réduit. Il consomme beaucoup de stimulants depuis quelques jours. Quelle erreur faut-il éviter ?","competency":"n2.causality","choices":["Attribuer automatiquement le tableau aux stimulants","Considérer simultanément temporalité des symptômes et exposition","Écarter toute cause secondaire"],"ask_leader":true,"debrief":"La présence d’une substance ne démontre pas sa causalité. Il faut reconstruire l’ordre d’apparition des phénomènes.","discriminant":"Temporalité exposition–syndrome.","trap":"La coexistence temporelle pousse facilement à conclure à tort à une causalité."},{"kind":"multi","label":"Enquête","prompt":"Quelles deux informations sont les plus utiles pour établir la relation causale ?","competency":"n2.evidence","choices":["Date précise de début de l’activation","Date d’introduction ou d’augmentation de la substance/médicament","Marque commerciale du stimulant","Préférence alimentaire récente"],"required":2,"max":2,"debrief":"Le début des symptômes et le début de l’exposition sont les données qui permettent de tester l’hypothèse causale.","discriminant":"Séquence temporelle.","trap":"La marque ou les détails accessoires n’aident pas à établir la causalité."},{"kind":"single","label":"Nouvelle donnée","prompt":"La réduction du besoin de sommeil et l’augmentation d’énergie ont commencé cinq jours avant l’augmentation des stimulants.","competency":"n2.causality","choices":"Quelle interprétation est la plus rigoureuse ?","reveal":["Les stimulants expliquent probablement le début","Ils peuvent amplifier le tableau mais expliquent mal son déclenchement","Ils deviennent sans aucune pertinence"],"ask_leader":true,"debrief":"Une exposition qui augmente après le début du syndrome peut l’amplifier sans bien expliquer son déclenchement.","discriminant":"Syndrome antérieur à l’exposition accrue.","trap":"La substance reste visible dans le dossier et peut donc capter excessivement le raisonnement."},{"kind":"single","label":"Vous maintenez ?","prompt":"Après arrêt du stimulant, l’activation syndromique persiste plusieurs jours sans diminution nette.","competency":"n2.revision","choices":"Que devient l’hypothèse induite ?","reveal":["Elle gagne du poids","Elle perd du poids au profit d’un épisode primaire à caractériser","Elle est définitivement prouvée"],"ask_leader":true,"debrief":"La persistance du syndrome après arrêt de l’exposition affaiblit encore l’hypothèse strictement induite.","discriminant":"Persistance au-delà de l’exposition.","trap":"Il est tentant de maintenir l’hypothèse initiale malgré les données nouvelles."},{"kind":"single","label":"Argument décisif","prompt":"Quelle donnée est la plus discriminante ?","competency":"n2.discrimination","choices":["La présence d’une substance","La séquence temporelle entre exposition et syndrome","L’intensité subjective du stress"],"debrief":"L’argument central est l’ordre temporel, pas la simple présence d’un facteur.","discriminant":"Chronologie causale.","trap":"Présence et causalité sont facilement confondues."},{"kind":"final","label":"Signature","prompt":"Quelle branche est actuellement la mieux soutenue ?","competency":"n2.formulation","diagnosis_choices":["Trouble bipolaire primaire","Trouble de l’humeur induit par substance ou médicament","Anxiété avec agitation","TDAH"],"argument_choices":["Présence de stimulants","Syndrome précédant l’augmentation de l’exposition et persistant après arrêt","Agitation marquée"],"debrief":"À ce stade, un épisode primaire à caractériser est mieux soutenu qu’un trouble strictement induit.","discriminant":"Début avant exposition accrue + persistance après arrêt.","trap":"La substance reste un modificateur possible sans être nécessairement l’étiologie principale."}],"references":["DSM-5-TR — Trouble bipolaire induit par substance/médicament","Shorter Oxford Textbook of Psychiatry — Assessment of mania"]},"en":{"title":"Chronology first","subtitle":"Presence is not causality.","intro":"Presence is not causality.","hypotheses":["Primary bipolar disorder","Substance/medication-induced mood disorder","Anxiety with agitation","ADHD"],"steps":[{"kind":"single","label":"First impression","prompt":"An adult with no known history has one week of agitation, irritability and reduced sleep. Stimulant use increased a few days ago. Which error should be avoided?","competency":"n2.causality","choices":["Automatically attributing the presentation to stimulants","Considering symptom chronology and exposure together","Excluding all secondary causes"],"ask_leader":true},{"kind":"multi","label":"Inquiry","prompt":"Which two pieces of information are most useful to establish causality?","competency":"n2.evidence","choices":["Exact onset of activation","Date of starting or increasing the substance/medication","Commercial brand of the stimulant","Recent food preferences"],"required":2,"max":2},{"kind":"single","label":"New information","prompt":"Reduced need for sleep and increased energy began five days before stimulant use increased.","competency":"n2.causality","choices":"What is the most rigorous interpretation?","reveal":["Stimulants probably explain onset","They may amplify the picture but poorly explain onset","They are completely irrelevant"],"ask_leader":true},{"kind":"single","label":"Do you maintain?","prompt":"After the stimulant is stopped, the syndromic activation persists for several days without clear reduction.","competency":"n2.revision","choices":"What happens to the induced hypothesis?","reveal":["It gains weight","It loses weight in favor of a primary episode that still needs characterization","It is definitively proven"],"ask_leader":true},{"kind":"single","label":"Decisive argument","prompt":"Which datum is most discriminating?","competency":"n2.discrimination","choices":["Presence of a substance","Temporal sequence between exposure and syndrome","Subjective stress intensity"]},{"kind":"final","label":"Signature","prompt":"Which branch is currently best supported?","competency":"n2.formulation","diagnosis_choices":["Primary bipolar disorder","Substance/medication-induced mood disorder","Anxiety with agitation","ADHD"],"argument_choices":["Presence of stimulants","Syndrome preceded increased exposure and persisted after stopping it","Marked agitation"]}],"references":["DSM-5-TR — Trouble bipolaire induit par substance/médicament","Shorter Oxford Textbook of Psychiatry — Assessment of mania"]}}'::jsonb,'{"steps":[{"kind":"single","correct":1,"certainty_target":75,"leader_correct":[0,1]},{"kind":"multi","correct":[0,1],"certainty_target":90},{"kind":"single","correct":1,"certainty_target":90,"leader_correct":[0]},{"kind":"single","correct":1,"certainty_target":85,"leader_correct":[0],"revision":"maintain"},{"kind":"single","correct":1},{"kind":"final","diagnosis":0,"argument":1,"certainty_target":80}]}'::jsonb,100),
(4,'bipolar','{"fr":{"title":"Labilité n’est pas bipolarité","subtitle":"Le tempo clinique compte autant que l’intensité.","intro":"Le tempo clinique compte autant que l’intensité.","hypotheses":["Épisodes thymiques bipolaires","Labilité émotionnelle réactive","Épisode maniaque actuel","Cause secondaire"],"steps":[{"kind":"single","label":"Première impression","prompt":"Une patiente décrit des changements d’humeur plusieurs fois dans la même journée, le plus souvent après des conflits interpersonnels. Quelle donnée manque avant de parler de bipolarité ?","competency":"n2.temporality","choices":["Le caractère épisodique autonome et la durée des changements","Le nombre exact de conflits","Le niveau d’études"],"ask_leader":true,"debrief":"La bipolarité implique des épisodes distincts ; une variation brève et réactive exige d’abord une analyse temporelle.","discriminant":"Épisodicité autonome.","trap":"L’intensité émotionnelle peut donner une impression trompeuse de bipolarité."},{"kind":"multi","label":"Enquête","prompt":"Quelles deux informations discriminent le mieux labilité réactive et épisode thymique ?","competency":"n2.evidence","choices":["Durée habituelle des changements","Existence de périodes distinctes avec modification durable de l’énergie et de l’activité","Couleur émotionnelle dominante","Nombre de proches disponibles"],"required":2,"max":2,"debrief":"Durée et modification soutenue de l’énergie/activité discriminent mieux que le simple contenu émotionnel.","discriminant":"Temporalité + changement du baseline.","trap":"Les émotions fortes attirent l’attention mais sont peu spécifiques."},{"kind":"single","label":"Nouvelle donnée","prompt":"Les changements durent de quelques minutes à quelques heures, sont fortement liés aux événements et reviennent au niveau habituel une fois le conflit résolu.","competency":"n2.temporality","choices":"Quel cadre gagne du poids ?","reveal":["Labilité émotionnelle réactive","Épisode maniaque","Hypomanie certaine"],"ask_leader":true,"debrief":"Des oscillations de minutes à heures, liées aux événements, soutiennent davantage une labilité réactive qu’un épisode thymique.","discriminant":"Réactivité événementielle brève.","trap":"Le terme ''mood swings'' peut conduire à surdiagnostiquer une bipolarité."},{"kind":"single","label":"Vous maintenez ?","prompt":"Aucune période indépendante de plusieurs jours avec augmentation persistante d’énergie, réduction du besoin de sommeil ou changement observable du fonctionnement n’est retrouvée.","competency":"n2.revision","choices":"Que faire de l’hypothèse bipolaire ?","reveal":["La maintenir comme diagnostic principal","La rétrograder sans nier toute possibilité future","La confirmer sur la seule intensité émotionnelle"],"ask_leader":true,"debrief":"En l’absence de période autonome soutenue, l’hypothèse bipolaire doit être rétrogradée sans être artificiellement éliminée.","discriminant":"Absence d’épisode distinct.","trap":"Fermer définitivement une branche est aussi problématique que la survaloriser."},{"kind":"single","label":"Argument décisif","prompt":"Quel contraste est le plus discriminant ?","competency":"n2.discrimination","choices":["Intensité émotionnelle","Réactivité brève versus épisode distinct et soutenu","Irritabilité versus tristesse"],"debrief":"Le contraste discriminant concerne le tempo : réactivité brève versus épisode soutenu.","discriminant":"Temporalité.","trap":"L’irritabilité ou la tristesse isolées ne permettent pas de trancher."},{"kind":"final","label":"Signature","prompt":"Quel cadre décrit le mieux les données actuelles ?","competency":"n2.formulation","diagnosis_choices":["Épisodes thymiques bipolaires","Labilité émotionnelle réactive","Épisode maniaque actuel","Cause secondaire"],"argument_choices":["Humeur très intense","Variations brèves, réactives et non épisodiques","Présence d’irritabilité"],"debrief":"La formulation la plus prudente décrit une labilité réactive sur les données actuelles.","discriminant":"Variations brèves et dépendantes du contexte.","trap":"Une étiquette diagnostique ne doit pas dépasser les données disponibles."}],"references":["Jansson & Nordgaard — The Psychiatric Interview","DSM-5-TR — Troubles bipolaires et apparentés"]},"en":{"title":"Lability is not bipolarity","subtitle":"Clinical timing matters as much as intensity.","intro":"Clinical timing matters as much as intensity.","hypotheses":["Bipolar mood episodes","Reactive emotional lability","Current manic episode","Secondary cause"],"steps":[{"kind":"single","label":"First impression","prompt":"A patient reports mood shifts several times within the same day, usually after interpersonal conflict. What information is missing before calling this bipolarity?","competency":"n2.temporality","choices":["Autonomous episodicity and duration of changes","Exact number of conflicts","Education level"],"ask_leader":true},{"kind":"multi","label":"Inquiry","prompt":"Which two pieces of information best discriminate reactive lability from a mood episode?","competency":"n2.evidence","choices":["Usual duration of shifts","Distinct periods with sustained changes in energy and activity","Dominant emotional tone","Number of available relatives"],"required":2,"max":2},{"kind":"single","label":"New information","prompt":"Changes last minutes to hours, are tightly event-related and return to baseline when the conflict resolves.","competency":"n2.temporality","choices":"Which framework gains weight?","reveal":["Reactive emotional lability","Manic episode","Definite hypomania"],"ask_leader":true},{"kind":"single","label":"Do you maintain?","prompt":"No independent multi-day period with sustained increased energy, reduced need for sleep or observable functional change is found.","competency":"n2.revision","choices":"What should happen to the bipolar hypothesis?","reveal":["Keep it as the primary diagnosis","Downgrade it without denying all future possibility","Confirm it from emotional intensity alone"],"ask_leader":true},{"kind":"single","label":"Decisive argument","prompt":"Which contrast is most discriminating?","competency":"n2.discrimination","choices":["Emotional intensity","Brief reactivity versus a distinct sustained episode","Irritability versus sadness"]},{"kind":"final","label":"Signature","prompt":"Which framework best describes the current data?","competency":"n2.formulation","diagnosis_choices":["Bipolar mood episodes","Reactive emotional lability","Current manic episode","Secondary cause"],"argument_choices":["Very intense mood","Brief reactive non-episodic shifts","Presence of irritability"]}],"references":["Jansson & Nordgaard — The Psychiatric Interview","DSM-5-TR — Troubles bipolaires et apparentés"]}}'::jsonb,'{"steps":[{"kind":"single","correct":0,"certainty_target":75,"leader_correct":[0,1]},{"kind":"multi","correct":[0,1],"certainty_target":85},{"kind":"single","correct":0,"certainty_target":90,"leader_correct":[1]},{"kind":"single","correct":1,"certainty_target":90,"leader_correct":[1],"revision":"maintain"},{"kind":"single","correct":1},{"kind":"final","diagnosis":1,"argument":1,"certainty_target":90}]}'::jsonb,100),
(5,'bipolar','{"fr":{"title":"Premier épisode tardif","subtitle":"Quand l’âge de début change, l’arbre doit s’ouvrir.","intro":"Quand l’âge de début change, l’arbre doit s’ouvrir.","hypotheses":["Premier épisode maniaque primaire","Cause secondaire médicale ou médicamenteuse","Trouble bipolaire I déjà connu","Réaction anxieuse"],"steps":[{"kind":"single","label":"Première impression","prompt":"À 58 ans, une personne sans antécédent thymique connu développe pour la première fois une activation marquée. Quelle branche doit rester particulièrement visible ?","competency":"n2.branching","choices":["Cause secondaire médicale ou médicamenteuse","TDAH ancien","Cyclothymie"],"ask_leader":true,"debrief":"Un premier épisode d’activation tardif impose d’ouvrir largement les causes secondaires, médicales et médicamenteuses.","discriminant":"Âge de début inhabituel + absence d’histoire antérieure.","trap":"L’apparence typiquement maniaque peut faire oublier l’étiologie."},{"kind":"multi","label":"Enquête","prompt":"Quelles deux recherches sont prioritaires pour l’étiologie ?","competency":"n2.evidence","choices":["Médicaments et substances récemment introduits ou modifiés","Examen somatique/neurologique et contexte médical","Style vestimentaire habituel","Préférence musicale"],"required":2,"max":2,"debrief":"L’exposition médicamenteuse récente et l’examen somatique/neurologique sont directement pertinents pour l’étiologie.","discriminant":"Cause secondaire vérifiable.","trap":"Les informations de contexte non causal peuvent distraire."},{"kind":"single","label":"Nouvelle donnée","prompt":"Un traitement corticoïde à dose élevée a été introduit peu avant le changement comportemental.","competency":"n2.causality","choices":"Quelle hypothèse monte dans la hiérarchie ?","reveal":["Cause médicamenteuse","Trouble bipolaire I certain","Simple stress"],"ask_leader":true,"debrief":"La proximité temporelle avec un corticoïde fait monter l’hypothèse médicamenteuse sans la rendre automatiquement certaine.","discriminant":"Lien temporel exposition–symptômes.","trap":"Une association temporelle forte reste à confronter à l’évolution."},{"kind":"single","label":"Vous maintenez ?","prompt":"L’activation régresse progressivement après adaptation du traitement et aucune histoire d’épisodes spontanés comparables n’est retrouvée.","competency":"n2.revision","choices":"Quelle révision est la plus adaptée ?","reveal":["Renforcer une cause secondaire","Reclasser en trouble bipolaire I malgré tout","Ignorer la temporalité médicamenteuse"],"ask_leader":true,"debrief":"La régression après adaptation thérapeutique renforce encore l’hypothèse secondaire.","discriminant":"Évolution concordante après modification du facteur.","trap":"La tentation est de conserver une étiquette primaire une fois posée."},{"kind":"single","label":"Argument décisif","prompt":"Quel élément pèse le plus ?","competency":"n2.discrimination","choices":["Âge élevé seul","Proximité temporelle avec le traitement et évolution après modification","Irritabilité"],"debrief":"Ce n’est pas l’âge seul mais la convergence temporalité–exposition–évolution qui discrimine.","discriminant":"Faisceau causal concordant.","trap":"Un seul facteur démographique ne suffit jamais."},{"kind":"final","label":"Signature","prompt":"Quelle branche est la mieux soutenue ?","competency":"n2.formulation","diagnosis_choices":["Premier épisode maniaque primaire","Cause secondaire médicale ou médicamenteuse","Trouble bipolaire I déjà connu","Réaction anxieuse"],"argument_choices":["Première activation tardive","Lien temporel avec le traitement et évolution concordante","Absence de dépression"],"debrief":"Le cadre secondaire est ici le plus soutenu, sous réserve de l’évaluation clinique complète.","discriminant":"Lien médicamenteux et évolution.","trap":"Signer ''bipolaire'' sans intégrer l’étiologie serait une fermeture prématurée."}],"references":["DSM-5-TR — Causes secondaires et médicaments","Shorter Oxford Textbook of Psychiatry — Assessment of mania"]},"en":{"title":"Late first episode","subtitle":"When age at onset changes, the tree must open.","intro":"When age at onset changes, the tree must open.","hypotheses":["First primary manic episode","Secondary medical or medication cause","Known bipolar I disorder","Anxiety reaction"],"steps":[{"kind":"single","label":"First impression","prompt":"At age 58, a person with no known mood history develops marked activation for the first time. Which branch must remain especially visible?","competency":"n2.branching","choices":["Secondary medical or medication cause","Longstanding ADHD","Cyclothymia"],"ask_leader":true},{"kind":"multi","label":"Inquiry","prompt":"Which two etiological inquiries are priorities?","competency":"n2.evidence","choices":["Recently introduced or changed medications/substances","Physical/neurological examination and medical context","Usual clothing style","Music preference"],"required":2,"max":2},{"kind":"single","label":"New information","prompt":"High-dose corticosteroid treatment was introduced shortly before the behavioral change.","competency":"n2.causality","choices":"Which hypothesis rises in the hierarchy?","reveal":["Medication-related cause","Definite bipolar I disorder","Simple stress"],"ask_leader":true},{"kind":"single","label":"Do you maintain?","prompt":"Activation gradually recedes after treatment adjustment and no history of comparable spontaneous episodes is found.","competency":"n2.revision","choices":"What revision is most appropriate?","reveal":["Strengthen a secondary cause","Reclassify as bipolar I anyway","Ignore medication chronology"],"ask_leader":true},{"kind":"single","label":"Decisive argument","prompt":"Which element weighs most?","competency":"n2.discrimination","choices":["Older age alone","Temporal proximity to treatment and concordant evolution after modification","Irritability"]},{"kind":"final","label":"Signature","prompt":"Which branch is best supported?","competency":"n2.formulation","diagnosis_choices":["First primary manic episode","Secondary medical or medication cause","Known bipolar I disorder","Anxiety reaction"],"argument_choices":["Late first activation","Temporal link with treatment and concordant evolution","Absence of depression"]}],"references":["DSM-5-TR — Causes secondaires et médicaments","Shorter Oxford Textbook of Psychiatry — Assessment of mania"]}}'::jsonb,'{"steps":[{"kind":"single","correct":0,"certainty_target":85,"leader_correct":[1]},{"kind":"multi","correct":[0,1],"certainty_target":90},{"kind":"single","correct":0,"certainty_target":90,"leader_correct":[1]},{"kind":"single","correct":0,"certainty_target":90,"leader_correct":[1],"revision":"maintain"},{"kind":"single","correct":1},{"kind":"final","diagnosis":1,"argument":1,"certainty_target":90}]}'::jsonb,100),
(6,'bipolar','{"fr":{"title":"Compatible n’est pas discriminant","subtitle":"Un symptôme partagé ne tranche pas le différentiel.","intro":"Un symptôme partagé ne tranche pas le différentiel.","hypotheses":["TDAH primaire","Épisode thymique","Trouble anxieux","Cause médicale"],"steps":[{"kind":"single","label":"Première impression","prompt":"Un patient de 37 ans présente distractibilité, logorrhée et activité accrue apparues depuis dix jours. Le fonctionnement antérieur était stable. Quelle donnée fragilise le plus l’hypothèse de TDAH primaire ?","competency":"n2.evidence","choices":["Début épisodique récent","Distractibilité","Activité accrue"],"ask_leader":true,"debrief":"Distractibilité et activité accrue sont compatibles avec plusieurs cadres ; un début épisodique récent fragilise un TDAH développemental.","discriminant":"Trait versus état.","trap":"La ressemblance symptomatique peut faire oublier l’âge de début et le cours."},{"kind":"multi","label":"Enquête","prompt":"Quelles deux informations discriminent le mieux TDAH et épisode thymique ?","competency":"n2.evidence","choices":["Présence de symptômes similaires depuis l’enfance","Existence d’un changement net par rapport au fonctionnement habituel","Préférence pour plusieurs tâches","Niveau d’études"],"required":2,"max":2,"debrief":"L’histoire depuis l’enfance et le changement par rapport au baseline sont les données les plus discriminantes.","discriminant":"Persistance développementale versus épisode acquis.","trap":"La multitâche actuelle est peu spécifique."},{"kind":"single","label":"Nouvelle donnée","prompt":"L’entourage confirme l’absence de difficultés attentionnelles persistantes auparavant et décrit un changement brutal avec sommeil réduit et énergie accrue.","competency":"n2.branching","choices":"Quelle branche gagne du poids ?","reveal":["TDAH primaire","Épisode thymique","Aucune"],"ask_leader":true,"debrief":"L’absence d’histoire attentionnelle persistante et le changement brutal déplacent l’arbre vers un épisode thymique.","discriminant":"Début net sur fonctionnement antérieur stable.","trap":"Un symptôme actuel peut sembler suffisant s’il correspond à un critère connu du TDAH."},{"kind":"single","label":"Vous maintenez ?","prompt":"Les symptômes forment une période nettement délimitée et contrastent avec le fonctionnement intercritique.","competency":"n2.revision","choices":"Quelle décision est la plus rigoureuse ?","reveal":["Prioriser l’hypothèse épisodique tout en évaluant le différentiel","Diagnostiquer un TDAH sur la distractibilité actuelle","Conclure sans rechercher la sévérité"],"ask_leader":true,"debrief":"Le bon raisonnement priorise l’hypothèse épisodique tout en gardant le différentiel ouvert.","discriminant":"Épisodicité et baseline.","trap":"Prioriser n’est pas équivalent à fermer les autres branches."},{"kind":"single","label":"Argument décisif","prompt":"Quel principe est central ?","competency":"n2.discrimination","choices":["Un symptôme suffit à identifier le trouble","Le caractère trait versus état et l’épisodicité","L’intensité de la parole seule"],"debrief":"Le principe discriminant est trait versus état.","discriminant":"Cours longitudinal.","trap":"Compter les symptômes partagés ne remplace pas l’analyse du cours."},{"kind":"final","label":"Signature","prompt":"Quel cadre est le mieux soutenu ?","competency":"n2.formulation","diagnosis_choices":["TDAH primaire","Épisode thymique","Trouble anxieux","Cause médicale"],"argument_choices":["Distractibilité actuelle","Début épisodique récent avec changement du baseline","Parole abondante"],"debrief":"L’épisode thymique est actuellement mieux soutenu que le TDAH primaire.","discriminant":"Début épisodique récent.","trap":"La distractibilité seule ne doit pas dominer la formulation finale."}],"references":["DSM-5-TR — Diagnostic différentiel TDAH/manie","Jansson & Nordgaard — Épisodicité et histoire longitudinale"]},"en":{"title":"Compatible is not discriminating","subtitle":"A shared symptom does not settle the differential.","intro":"A shared symptom does not settle the differential.","hypotheses":["Primary ADHD","Mood episode","Anxiety disorder","Medical cause"],"steps":[{"kind":"single","label":"First impression","prompt":"A 37-year-old has distractibility, increased speech and activity for ten days. Previous functioning was stable. Which datum weakens primary ADHD most?","competency":"n2.evidence","choices":["Recent episodic onset","Distractibility","Increased activity"],"ask_leader":true},{"kind":"multi","label":"Inquiry","prompt":"Which two pieces of information best discriminate ADHD from a mood episode?","competency":"n2.evidence","choices":["Similar symptoms since childhood","Clear change from usual functioning","Preference for multitasking","Education level"],"required":2,"max":2},{"kind":"single","label":"New information","prompt":"Collateral history confirms no persistent past attention problems and a sudden change with reduced sleep and increased energy.","competency":"n2.branching","choices":"Which branch gains weight?","reveal":["Primary ADHD","Mood episode","Neither"],"ask_leader":true},{"kind":"single","label":"Do you maintain?","prompt":"Symptoms form a clearly delimited period and contrast with inter-episode functioning.","competency":"n2.revision","choices":"What is the most rigorous decision?","reveal":["Prioritize the episodic hypothesis while continuing the differential","Diagnose ADHD from current distractibility","Conclude without assessing severity"],"ask_leader":true},{"kind":"single","label":"Decisive argument","prompt":"Which principle is central?","competency":"n2.discrimination","choices":["One symptom identifies the disorder","Trait versus state and episodicity","Speech intensity alone"]},{"kind":"final","label":"Signature","prompt":"Which framework is best supported?","competency":"n2.formulation","diagnosis_choices":["Primary ADHD","Mood episode","Anxiety disorder","Medical cause"],"argument_choices":["Current distractibility","Recent episodic onset with change from baseline","Increased speech"]}],"references":["DSM-5-TR — Diagnostic différentiel TDAH/manie","Jansson & Nordgaard — Épisodicité et histoire longitudinale"]}}'::jsonb,'{"steps":[{"kind":"single","correct":0,"certainty_target":85,"leader_correct":[1]},{"kind":"multi","correct":[0,1],"certainty_target":90},{"kind":"single","correct":1,"certainty_target":90,"leader_correct":[1]},{"kind":"single","correct":0,"certainty_target":90,"leader_correct":[1],"revision":"maintain"},{"kind":"single","correct":1},{"kind":"final","diagnosis":1,"argument":1,"certainty_target":90}]}'::jsonb,100),
(7,'bipolar','{"fr":{"title":"Vous maintenez ?","subtitle":"Une seule donnée peut changer le niveau de sévérité.","intro":"Une seule donnée peut changer le niveau de sévérité.","hypotheses":["Hypomanie","Manie","Activation anxieuse","Cyclothymie"],"steps":[{"kind":"single","label":"Première impression","prompt":"Une activation thymique de cinq jours s’accompagne d’une augmentation d’énergie, de parole et de projets, sans retentissement majeur initial.","competency":"n2.thresholds","choices":"Quel niveau de sévérité est le plus plausible à ce stade ?","reveal":["Hypomanie possible","Manie certaine","Cyclothymie"],"ask_leader":true,"debrief":"Avec une activation de cinq jours sans retentissement majeur, une hypomanie est plausible avant les données de sévérité supplémentaires.","discriminant":"Durée compatible + sévérité initialement limitée.","trap":"Le mot ''activation'' ne suffit pas encore à classer manie/hypomanie."},{"kind":"multi","label":"Enquête","prompt":"Quelles deux données sont les plus importantes pour distinguer hypomanie et manie ?","competency":"n2.evidence","choices":["Retentissement fonctionnel global","Présence de symptômes psychotiques ou nécessité d’hospitalisation","Nombre exact de messages envoyés","Préférence vestimentaire"],"required":2,"max":2,"debrief":"Retentissement majeur, psychose et hospitalisation sont des données structurantes pour la distinction de sévérité.","discriminant":"Sévérité fonctionnelle/psychotique.","trap":"Le nombre de symptômes n’est pas le seul déterminant."},{"kind":"single","label":"Nouvelle donnée","prompt":"Le patient développe des idées délirantes congruentes à l’humeur au cours du même épisode.","competency":"n2.thresholds","choices":"Que devient la classification ?","reveal":["Elle reste hypomaniaque","L’épisode est maniaque par définition","Elle devient cyclothymique"],"ask_leader":true,"debrief":"La présence de psychose au cours de l’épisode fait basculer la classification vers la manie.","discriminant":"Psychose.","trap":"La durée de cinq jours peut inciter à rester fixé sur l’hypomanie."},{"kind":"single","label":"Vous maintenez ?","prompt":"La durée totale reste de cinq jours.","competency":"n2.revision","choices":"Le critère de durée empêche-t-il la classification maniaque ?","reveal":["Oui, une semaine est toujours indispensable","Non, la sévérité/psychose peut suffire à classer l’épisode comme maniaque","Seulement si le sommeil est normal"],"ask_leader":true,"debrief":"Une durée inférieure à une semaine n’empêche pas la manie quand la sévérité atteint un seuil définitoire.","discriminant":"Sévérité supérieure au critère de durée simple.","trap":"Appliquer mécaniquement un seuil temporel sans intégrer la sévérité est une erreur de checklist."},{"kind":"single","label":"Argument décisif","prompt":"Quel élément a réellement changé la catégorie ?","competency":"n2.discrimination","choices":["La durée de cinq jours","La présence de psychose au cours de l’épisode","Le nombre de projets"],"debrief":"La donnée qui change la catégorie est la psychose.","discriminant":"Psychose au cours de l’épisode.","trap":"Les autres symptômes étaient déjà présents avant le basculement."},{"kind":"final","label":"Signature","prompt":"Quelle classification finale est la mieux soutenue ?","competency":"n2.formulation","diagnosis_choices":["Hypomanie","Manie","Activation anxieuse","Cyclothymie"],"argument_choices":["Durée de cinq jours","Psychose au cours de l’épisode","Augmentation de la parole"],"debrief":"La classification finale est maniaque.","discriminant":"Psychose = niveau maniaque.","trap":"La signature doit intégrer la donnée nouvelle, pas l’impression initiale."}],"references":["DSM-5-TR — Troubles bipolaires et apparentés","Shorter Oxford Textbook of Psychiatry — Bipolar disorder"]},"en":{"title":"Do you maintain?","subtitle":"One datum can change the severity threshold.","intro":"One datum can change the severity threshold.","hypotheses":["Hypomania","Mania","Anxious activation","Cyclothymia"],"steps":[{"kind":"single","label":"First impression","prompt":"A five-day mood activation includes increased energy, speech and projects, initially without marked impairment.","competency":"n2.thresholds","choices":"Which severity level is most plausible at this stage?","reveal":["Possible hypomania","Definite mania","Cyclothymia"],"ask_leader":true},{"kind":"multi","label":"Inquiry","prompt":"Which two data are most important to distinguish hypomania from mania?","competency":"n2.evidence","choices":["Overall functional impairment","Psychotic symptoms or need for hospitalization","Exact number of messages sent","Clothing preference"],"required":2,"max":2},{"kind":"single","label":"New information","prompt":"The patient develops mood-congruent delusions during the same episode.","competency":"n2.thresholds","choices":"How does classification change?","reveal":["It remains hypomanic","The episode is manic by definition","It becomes cyclothymic"],"ask_leader":true},{"kind":"single","label":"Do you maintain?","prompt":"Total duration remains five days.","competency":"n2.revision","choices":"Does duration prevent manic classification?","reveal":["Yes, one week is always mandatory","No, severity/psychosis can classify the episode as manic","Only if sleep is normal"],"ask_leader":true},{"kind":"single","label":"Decisive argument","prompt":"Which element truly changed the category?","competency":"n2.discrimination","choices":["Five-day duration","Psychosis during the episode","Number of projects"]},{"kind":"final","label":"Signature","prompt":"Which final classification is best supported?","competency":"n2.formulation","diagnosis_choices":["Hypomania","Mania","Anxious activation","Cyclothymia"],"argument_choices":["Five-day duration","Psychosis during the episode","Increased speech"]}],"references":["DSM-5-TR — Troubles bipolaires et apparentés","Shorter Oxford Textbook of Psychiatry — Bipolar disorder"]}}'::jsonb,'{"steps":[{"kind":"single","correct":0,"certainty_target":70,"leader_correct":[0]},{"kind":"multi","correct":[0,1],"certainty_target":90},{"kind":"single","correct":1,"certainty_target":95,"leader_correct":[1]},{"kind":"single","correct":1,"certainty_target":95,"leader_correct":[1],"revision":"maintain"},{"kind":"single","correct":1},{"kind":"final","diagnosis":1,"argument":1,"certainty_target":95}]}'::jsonb,100),
(8,'bipolar','{"fr":{"title":"Dépression sous tension","subtitle":"Activation simultanée ne signifie pas forcément hypomanie distincte.","intro":"Activation simultanée ne signifie pas forcément hypomanie distincte.","hypotheses":["Épisode dépressif avec caractéristiques mixtes","Épisode hypomaniaque distinct","Trouble anxieux","Épisode maniaque"],"steps":[{"kind":"single","label":"Première impression","prompt":"Pendant un épisode dépressif, une patiente présente simultanément accélération subjective de la pensée et augmentation de l’énergie, sans période séparée d’humeur élevée.","competency":"n2.mixed","choices":"Quel concept doit être évalué en priorité ?","reveal":["Caractéristiques mixtes","Hypomanie distincte certaine","Cyclothymie"],"ask_leader":true,"debrief":"Des symptômes d’activation simultanés à une dépression doivent faire évaluer une mixité avant de postuler un épisode hypomaniaque séparé.","discriminant":"Concomitance temporelle.","trap":"Les symptômes d’activation peuvent spontanément évoquer ''hypomanie''."},{"kind":"multi","label":"Enquête","prompt":"Quelles deux informations permettent de distinguer mixité et épisode hypomaniaque séparé ?","competency":"n2.evidence","choices":["Temporalité simultanée versus période distincte","Nombre et qualité des symptômes d’activation","Saison de naissance","Nombre de consultations passées"],"required":2,"max":2,"debrief":"La distinction dépend du fait que les symptômes surviennent dans le même épisode ou dans une période distincte.","discriminant":"Temporalité des pôles.","trap":"Le contenu symptomatique seul ne dit pas s’il existe deux épisodes."},{"kind":"single","label":"Nouvelle donnée","prompt":"Les symptômes d’activation surviennent uniquement pendant la dépression et disparaissent avec elle.","competency":"n2.mixed","choices":"Quelle hypothèse gagne du poids ?","reveal":["Épisode hypomaniaque distinct","Caractéristiques mixtes","Manie"],"ask_leader":true,"debrief":"Des symptômes qui apparaissent et disparaissent avec la dépression renforcent le cadre mixte.","discriminant":"Concomitance complète.","trap":"La présence d’énergie accrue peut sembler incompatible avec la dépression alors qu’elle peut coexister."},{"kind":"single","label":"Vous maintenez ?","prompt":"Aucune période autonome d’au moins plusieurs jours avec changement observable du fonctionnement n’est retrouvée.","competency":"n2.revision","choices":"Quelle révision est la plus rigoureuse ?","reveal":["Maintenir la mixité comme cadre à caractériser","Forcer un diagnostic de bipolarité II","Ignorer les symptômes d’activation"],"ask_leader":true,"debrief":"Sans période autonome d’activation, forcer une hypomanie séparée dépasse les données.","discriminant":"Absence d’épisode distinct.","trap":"Le désir de faire entrer le tableau dans une catégorie familière favorise la surclassification."},{"kind":"single","label":"Argument décisif","prompt":"Quel élément tranche principalement ?","competency":"n2.discrimination","choices":["L’existence de symptômes d’activation","Leur relation temporelle avec l’épisode dépressif","L’âge"],"debrief":"Le facteur discriminant est la relation temporelle entre activation et dépression.","discriminant":"Simultanéité versus succession.","trap":"Le nombre de symptômes ne remplace pas la chronologie."},{"kind":"final","label":"Signature","prompt":"Quel cadre décrit le mieux les données ?","competency":"n2.formulation","diagnosis_choices":["Épisode dépressif avec caractéristiques mixtes","Épisode hypomaniaque distinct","Trouble anxieux","Épisode maniaque"],"argument_choices":["Pensées rapides","Activation concomitante à la dépression sans épisode hypomaniaque distinct","Insomnie"],"debrief":"Le cadre mixte est le plus défendable sur les données fournies.","discriminant":"Activation concomitante à la dépression.","trap":"La signature doit respecter la structure temporelle observée."}],"references":["DSM-5-TR — Caractéristiques mixtes","Jansson & Nordgaard — Mixed states"]},"en":{"title":"Depression under tension","subtitle":"Concurrent activation does not necessarily mean distinct hypomania.","intro":"Concurrent activation does not necessarily mean distinct hypomania.","hypotheses":["Depressive episode with mixed features","Distinct hypomanic episode","Anxiety disorder","Manic episode"],"steps":[{"kind":"single","label":"First impression","prompt":"During a depressive episode, a patient simultaneously has subjective racing thoughts and increased energy, without a separate period of elevated mood.","competency":"n2.mixed","choices":"Which concept should be assessed first?","reveal":["Mixed features","Definite distinct hypomania","Cyclothymia"],"ask_leader":true},{"kind":"multi","label":"Inquiry","prompt":"Which two pieces of information distinguish mixed features from a separate hypomanic episode?","competency":"n2.evidence","choices":["Concurrent timing versus distinct period","Number and quality of activation symptoms","Season of birth","Number of past consultations"],"required":2,"max":2},{"kind":"single","label":"New information","prompt":"Activation symptoms occur only during depression and disappear with it.","competency":"n2.mixed","choices":"Which hypothesis gains weight?","reveal":["Distinct hypomanic episode","Mixed features","Mania"],"ask_leader":true},{"kind":"single","label":"Do you maintain?","prompt":"No autonomous multi-day period with observable functional change is found.","competency":"n2.revision","choices":"What is the most rigorous revision?","reveal":["Keep mixed features as the framework to characterize","Force bipolar II diagnosis","Ignore activation symptoms"],"ask_leader":true},{"kind":"single","label":"Decisive argument","prompt":"Which element mainly settles the issue?","competency":"n2.discrimination","choices":["Presence of activation symptoms","Their temporal relationship to the depressive episode","Age"]},{"kind":"final","label":"Signature","prompt":"Which framework best describes the data?","competency":"n2.formulation","diagnosis_choices":["Depressive episode with mixed features","Distinct hypomanic episode","Anxiety disorder","Manic episode"],"argument_choices":["Racing thoughts","Activation concurrent with depression without a distinct hypomanic episode","Insomnia"]}],"references":["DSM-5-TR — Caractéristiques mixtes","Jansson & Nordgaard — Mixed states"]}}'::jsonb,'{"steps":[{"kind":"single","correct":0,"certainty_target":80,"leader_correct":[0,1]},{"kind":"multi","correct":[0,1],"certainty_target":90},{"kind":"single","correct":1,"certainty_target":90,"leader_correct":[0]},{"kind":"single","correct":0,"certainty_target":90,"leader_correct":[0],"revision":"maintain"},{"kind":"single","correct":1},{"kind":"final","diagnosis":0,"argument":1,"certainty_target":90}]}'::jsonb,100),
(9,'bipolar','{"fr":{"title":"Le récit incomplet","subtitle":"Ce que le patient ne nomme pas peut rester cliniquement décisif.","intro":"Ce que le patient ne nomme pas peut rester cliniquement décisif.","hypotheses":["Trouble bipolaire II","Trouble dépressif majeur","Cyclothymie","Trouble anxieux"],"steps":[{"kind":"single","label":"Première impression","prompt":"Un patient déprimé nie tout épisode d’activation antérieur et décrit seulement des périodes où il « allait enfin bien ». Que faut-il éviter ?","competency":"n2.interview","choices":["Prendre l’absence de plainte comme preuve d’absence d’hypomanie","Explorer la qualité de ces périodes et l’information collatérale","Conclure immédiatement à un trouble bipolaire II"],"ask_leader":true,"debrief":"Un patient peut ne pas considérer une hypomanie comme pathologique ; l’absence de plainte n’est donc pas une preuve d’absence.","discriminant":"Reconnaissance subjective limitée de l’activation.","trap":"La consultation pour dépression focalise naturellement l’entretien sur la souffrance actuelle."},{"kind":"multi","label":"Enquête","prompt":"Quelles deux sources d’information sont les plus utiles ?","competency":"n2.evidence","choices":["Description détaillée du changement par rapport au baseline","Observation d’un proche lors des périodes concernées","Préférence du patient pour le diagnostic","Score de satisfaction de vie"],"required":2,"max":2,"debrief":"Le changement par rapport au baseline et l’observation des proches permettent de reconstruire une période que le patient banalise.","discriminant":"Information collatérale + baseline.","trap":"Préférence diagnostique et satisfaction ne caractérisent pas un épisode."},{"kind":"single","label":"Nouvelle donnée","prompt":"Un proche décrit plusieurs jours de sommeil réduit sans fatigue, expansivité inhabituelle et multiplication de projets, clairement différents du fonctionnement habituel.","competency":"n2.interview","choices":"Quelle conséquence ?","reveal":["L’information collatérale peut substantiellement renforcer l’hypothèse d’hypomanie","Elle ne peut jamais contribuer au diagnostic","Elle suffit seule à établir une manie"],"ask_leader":true,"debrief":"Un récit collatéral cohérent de changement syndromique peut fortement étayer l’hypomanie.","discriminant":"Changement observable par autrui.","trap":"La source collatérale peut être sous-valorisée à tort."},{"kind":"single","label":"Vous maintenez ?","prompt":"Le patient reconnaît ensuite que ces périodes étaient agréables et qu’il ne les avait jamais considérées comme pathologiques.","competency":"n2.revision","choices":"Quelle lecture est la plus juste ?","reveal":["Cela invalide l’hypomanie","Le manque de plainte initiale n’exclut pas une hypomanie","Cela prouve une personnalité hyperthymique"],"ask_leader":true,"debrief":"Le caractère agréable d’une période n’exclut pas une hypomanie.","discriminant":"Absence de plainte ≠ absence d’épisode.","trap":"Pathologique est parfois confondu avec subjectivement désagréable."},{"kind":"single","label":"Argument décisif","prompt":"Pourquoi l’information collatérale est-elle particulièrement utile ici ?","competency":"n2.discrimination","choices":["Parce qu’elle remplace toujours l’entretien","Parce que l’hypomanie peut être peu reconnue comme problématique par le patient","Parce que la famille décide du diagnostic"],"debrief":"L’information collatérale est utile parce que l’insight sur l’hypomanie peut être limité.","discriminant":"Reconnaissance subjective incomplète.","trap":"Les proches n’imposent pas le diagnostic ; ils enrichissent les données."},{"kind":"final","label":"Signature","prompt":"Quel cadre est le mieux soutenu si un épisode dépressif majeur et un épisode hypomaniaque suffisamment caractérisé sont établis, sans manie ?","competency":"n2.formulation","diagnosis_choices":["Trouble bipolaire II","Trouble dépressif majeur","Cyclothymie","Trouble anxieux"],"argument_choices":["Dépression actuelle seule","Association épisode dépressif majeur + hypomanie passée","Absence de plainte pendant l’activation"],"debrief":"Dépression majeure + hypomanie suffisamment caractérisée sans manie soutiennent un trouble bipolaire II.","discriminant":"Architecture longitudinale.","trap":"Le diagnostic ne doit pas dépendre uniquement de ce qui a motivé la consultation."}],"references":["DSM-5-TR — Bipolar II diagnostic features","Shorter Oxford Textbook — Collateral history in mania"]},"en":{"title":"The incomplete story","subtitle":"What the patient does not label may still be clinically decisive.","intro":"What the patient does not label may still be clinically decisive.","hypotheses":["Bipolar II disorder","Major depressive disorder","Cyclothymia","Anxiety disorder"],"steps":[{"kind":"single","label":"First impression","prompt":"A depressed patient denies any past activation and describes only periods when he ''finally felt well.'' What should be avoided?","competency":"n2.interview","choices":["Treating lack of complaint as proof that hypomania never occurred","Exploring the quality of those periods and collateral information","Immediately diagnosing bipolar II"],"ask_leader":true},{"kind":"multi","label":"Inquiry","prompt":"Which two sources of information are most useful?","competency":"n2.evidence","choices":["Detailed change from baseline","Collateral observation during the periods","Patient''s preferred diagnosis","Life satisfaction score"],"required":2,"max":2},{"kind":"single","label":"New information","prompt":"A relative describes several days of reduced sleep without fatigue, unusual expansiveness and multiple projects, clearly different from baseline.","competency":"n2.interview","choices":"What follows?","reveal":["Collateral information can substantially strengthen the hypomania hypothesis","Collateral information can never contribute to diagnosis","It alone establishes mania"],"ask_leader":true},{"kind":"single","label":"Do you maintain?","prompt":"The patient then acknowledges those periods felt good and were never considered pathological.","competency":"n2.revision","choices":"What is the best interpretation?","reveal":["This invalidates hypomania","Lack of initial complaint does not exclude hypomania","This proves hyperthymic personality"],"ask_leader":true},{"kind":"single","label":"Decisive argument","prompt":"Why is collateral information especially useful here?","competency":"n2.discrimination","choices":["It always replaces the interview","Hypomania may not be recognized as problematic by the patient","Family decides the diagnosis"]},{"kind":"final","label":"Signature","prompt":"Which framework is best supported if a major depressive episode and a sufficiently characterized past hypomanic episode are established, with no mania?","competency":"n2.formulation","diagnosis_choices":["Bipolar II disorder","Major depressive disorder","Cyclothymia","Anxiety disorder"],"argument_choices":["Current depression alone","Major depressive episode plus past hypomania","No complaint during activation"]}],"references":["DSM-5-TR — Bipolar II diagnostic features","Shorter Oxford Textbook — Collateral history in mania"]}}'::jsonb,'{"steps":[{"kind":"single","correct":1,"certainty_target":80,"leader_correct":[0,1]},{"kind":"multi","correct":[0,1],"certainty_target":90},{"kind":"single","correct":0,"certainty_target":90,"leader_correct":[0]},{"kind":"single","correct":1,"certainty_target":90,"leader_correct":[0],"revision":"maintain"},{"kind":"single","correct":1},{"kind":"final","diagnosis":0,"argument":1,"certainty_target":95}]}'::jsonb,100),
(10,'bipolar','{"fr":{"title":"Le score ne fait pas le diagnostic","subtitle":"La psychométrie mesure ; elle ne remplace pas le raisonnement clinique.","intro":"La psychométrie mesure ; elle ne remplace pas le raisonnement clinique.","hypotheses":["Trouble bipolaire confirmé par le score","Suspicion de bipolarité à approfondir longitudinalement","Trouble dépressif exclu","Manie confirmée par dépistage"],"steps":[{"kind":"single","label":"Première impression","prompt":"Chez un patient déprimé, un questionnaire de dépistage de bipolarité est positif. Quelle interprétation est correcte ?","competency":"n2.psychometrics","choices":["Le diagnostic est confirmé","Le résultat augmente la vigilance mais ne remplace pas l’anamnèse longitudinale","La dépression actuelle est exclue"],"ask_leader":true,"debrief":"Un dépistage positif modifie la probabilité et la vigilance ; il ne confirme pas à lui seul un trouble bipolaire.","discriminant":"Dépistage ≠ diagnostic.","trap":"Un nombre ou un seuil donne une impression trompeuse de certitude."},{"kind":"multi","label":"Enquête","prompt":"Quelles deux informations doivent compléter un dépistage positif ?","competency":"n2.evidence","choices":["Histoire détaillée d’épisodes d’activation","Retentissement, durée et changement par rapport au baseline","Score seul répété immédiatement","Préférence diagnostique du patient"],"required":2,"max":2,"debrief":"L’anamnèse des épisodes et leur retentissement restent nécessaires après un dépistage positif.","discriminant":"Reconstruction longitudinale.","trap":"Répéter le même score n’ajoute pas la donnée clinique manquante."},{"kind":"single","label":"Nouvelle donnée","prompt":"L’entretien ne retrouve aucune période syndromique distincte malgré plusieurs relances et une information collatérale concordante.","competency":"n2.psychometrics","choices":"Que faire du dépistage positif ?","reveal":["Le considérer comme preuve supérieure à l’entretien","Le replacer comme signal de dépistage non confirmatoire","Diagnostiquer une hypomanie sous-seuil"],"ask_leader":true,"debrief":"En l’absence d’épisode syndromique retrouvé, le score reste un signal de dépistage non confirmatoire.","discriminant":"Absence de validation clinique longitudinale.","trap":"Le résultat positif peut créer un biais d’ancrage."},{"kind":"single","label":"Vous maintenez ?","prompt":"Une échelle de sévérité maniaque est ensuite utilisée au suivi chez un patient dont la manie est déjà cliniquement établie.","competency":"n2.revision","choices":"Quel est son rôle principal ?","reveal":["Confirmer à nouveau le diagnostic","Quantifier la sévérité et son évolution","Mesurer le fonctionnement social"],"ask_leader":true,"debrief":"Une échelle de sévérité suit l’intensité d’un syndrome déjà établi ; elle ne remplace pas le diagnostic.","discriminant":"Mesure longitudinale de sévérité.","trap":"Confondre instrument de suivi et outil diagnostique est fréquent."},{"kind":"single","label":"Argument décisif","prompt":"Quel principe résume le mieux l’usage des échelles ?","competency":"n2.discrimination","choices":["Mesurer n’est pas diagnostiquer","Un score positif remplace l’entretien","Toutes les échelles mesurent la même dimension"],"debrief":"Le principe est simple : mesurer n’est pas diagnostiquer.","discriminant":"Fonction de l’instrument.","trap":"La précision numérique ne garantit pas la validité diagnostique."},{"kind":"final","label":"Signature","prompt":"Quel énoncé doit être retenu ?","competency":"n2.formulation","diagnosis_choices":["Trouble bipolaire confirmé par le score","Suspicion de bipolarité à approfondir longitudinalement","Trouble dépressif exclu","Manie confirmée par dépistage"],"argument_choices":["Score positif","Dépistage positif nécessitant une reconstruction longitudinale","Absence de fatigue"],"debrief":"La conclusion doit rester une suspicion à approfondir longitudinalement si les critères cliniques ne sont pas établis.","discriminant":"Anamnèse avant étiquette.","trap":"Le score ne doit pas dépasser la clinique."}],"references":["Shorter Oxford Textbook — YMRS/MADRS and follow-up","Jansson & Nordgaard — Diagnostic interview"]},"en":{"title":"A score is not a diagnosis","subtitle":"Psychometrics measures; it does not replace clinical reasoning.","intro":"Psychometrics measures; it does not replace clinical reasoning.","hypotheses":["Bipolar disorder confirmed by score","Bipolarity suspicion requiring longitudinal assessment","Depression excluded","Mania confirmed by screening"],"steps":[{"kind":"single","label":"First impression","prompt":"A bipolarity screening questionnaire is positive in a depressed patient. Which interpretation is correct?","competency":"n2.psychometrics","choices":["Diagnosis is confirmed","The result raises vigilance but does not replace longitudinal assessment","Current depression is excluded"],"ask_leader":true},{"kind":"multi","label":"Inquiry","prompt":"Which two pieces of information should complete a positive screen?","competency":"n2.evidence","choices":["Detailed history of activation episodes","Impairment, duration and change from baseline","Immediately repeat the score alone","Patient''s preferred diagnosis"],"required":2,"max":2},{"kind":"single","label":"New information","prompt":"Repeated interviewing and concordant collateral information reveal no distinct syndromic activation period.","competency":"n2.psychometrics","choices":"What should be done with the positive screen?","reveal":["Treat it as superior proof","Reframe it as a non-confirmatory screening signal","Diagnose subthreshold hypomania"],"ask_leader":true},{"kind":"single","label":"Do you maintain?","prompt":"A mania severity scale is later used in follow-up after mania has already been clinically established.","competency":"n2.revision","choices":"What is its main role?","reveal":["Reconfirm diagnosis","Quantify severity and change","Measure social functioning"],"ask_leader":true},{"kind":"single","label":"Decisive argument","prompt":"Which principle best summarizes scale use?","competency":"n2.discrimination","choices":["Measurement is not diagnosis","A positive score replaces interview","All scales measure the same dimension"]},{"kind":"final","label":"Signature","prompt":"Which statement should be retained?","competency":"n2.formulation","diagnosis_choices":["Bipolar disorder confirmed by score","Bipolarity suspicion requiring longitudinal assessment","Depression excluded","Mania confirmed by screening"],"argument_choices":["Positive score","Positive screening requires longitudinal reconstruction","Absence of fatigue"]}],"references":["Shorter Oxford Textbook — YMRS/MADRS and follow-up","Jansson & Nordgaard — Diagnostic interview"]}}'::jsonb,'{"steps":[{"kind":"single","correct":1,"certainty_target":90,"leader_correct":[1]},{"kind":"multi","correct":[0,1],"certainty_target":90},{"kind":"single","correct":1,"certainty_target":90,"leader_correct":[1]},{"kind":"single","correct":1,"certainty_target":90,"leader_correct":[1],"revision":"maintain"},{"kind":"single","correct":0},{"kind":"final","diagnosis":1,"argument":1,"certainty_target":95}]}'::jsonb,100),
(11,'bipolar','{"fr":{"title":"Diagnostic en appel","subtitle":"L’épisode actuel ne suffit pas à raconter le diagnostic longitudinal.","intro":"L’épisode actuel ne suffit pas à raconter le diagnostic longitudinal.","hypotheses":["Trouble dépressif majeur","Trouble bipolaire I","Trouble bipolaire II","Schizoaffectif"],"steps":[{"kind":"single","label":"Première impression","prompt":"Un patient consulte aujourd’hui pour une dépression caractérisée. Son dossier documente dix ans plus tôt un épisode maniaque complet.","competency":"n2.longitudinal","choices":"Quel principe longitudinal s’applique ?","reveal":["Le diagnostic actuel dépend uniquement de l’épisode présent","Un antécédent maniaque reste structurant pour le diagnostic longitudinal","La manie ancienne est sans pertinence"],"ask_leader":true,"debrief":"Le diagnostic bipolaire est longitudinal : un épisode maniaque authentifié reste structurant même si le patient est aujourd’hui déprimé.","discriminant":"Antécédent maniaque.","trap":"L’état présent peut masquer l’architecture de la maladie."},{"kind":"multi","label":"Enquête","prompt":"Quelles deux vérifications sont les plus importantes avant d’intégrer l’ancien épisode ?","competency":"n2.evidence","choices":["Qualité de la documentation de l’épisode maniaque","Exclusion d’une cause induite/secondaire à l’époque","Durée de la dépression actuelle uniquement","Préférence actuelle du patient"],"required":2,"max":2,"debrief":"Avant d’intégrer un ancien épisode, il faut vérifier sa qualité diagnostique et l’absence de cause induite/secondaire.","discriminant":"Validité de l’épisode ancien.","trap":"Un vieux diagnostic peut être recopié sans réévaluation."},{"kind":"single","label":"Nouvelle donnée","prompt":"Le dossier ancien décrit une semaine d’humeur expansive, énergie accrue, retentissement majeur et absence de cause induite identifiée.","competency":"n2.longitudinal","choices":"Quel diagnostic longitudinal gagne nettement ?","reveal":["Trouble bipolaire I","Trouble bipolaire II","Trouble dépressif majeur"],"ask_leader":true,"debrief":"Une manie bien documentée fait fortement soutenir le trouble bipolaire I.","discriminant":"Épisode maniaque authentifié.","trap":"La dépression actuelle peut pousser vers une lecture unipolaire."},{"kind":"single","label":"Vous maintenez ?","prompt":"L’épisode actuel est exclusivement dépressif, sans symptôme maniaque.","competency":"n2.revision","choices":"Cela modifie-t-il le diagnostic longitudinal ?","reveal":["Oui, il devient trouble dépressif majeur","Non, l’antécédent de manie reste déterminant","Oui, il devient bipolaire II"],"ask_leader":true,"debrief":"L’absence de manie actuelle ne retire pas l’antécédent maniaque du diagnostic longitudinal.","discriminant":"Histoire de vie entière.","trap":"Confondre épisode actuel et diagnostic longitudinal est le piège central."},{"kind":"single","label":"Argument décisif","prompt":"Quelle donnée structure le diagnostic sur la vie entière ?","competency":"n2.discrimination","choices":["Le symptôme du jour","L’existence d’au moins un épisode maniaque authentifié","Le nombre d’épisodes dépressifs"],"debrief":"Un seul épisode maniaque authentifié est structurant pour le trouble bipolaire I.","discriminant":"Antécédent de manie.","trap":"Le nombre de dépressions n’annule pas la manie passée."},{"kind":"final","label":"Signature","prompt":"Quel diagnostic longitudinal est le mieux soutenu ?","competency":"n2.formulation","diagnosis_choices":["Trouble dépressif majeur","Trouble bipolaire I","Trouble bipolaire II","Schizoaffectif"],"argument_choices":["Dépression actuelle","Antécédent maniaque documenté","Absence de manie actuelle"],"debrief":"La signature doit rester trouble bipolaire I sur l’histoire disponible.","discriminant":"Manie documentée antérieure.","trap":"Le diagnostic ne se réinitialise pas à chaque nouvel épisode."}],"references":["DSM-5-TR — Troubles bipolaires et apparentés","Jansson & Nordgaard — The Psychiatric Interview"]},"en":{"title":"Diagnosis under appeal","subtitle":"The current episode does not define the lifetime diagnosis by itself.","intro":"The current episode does not define the lifetime diagnosis by itself.","hypotheses":["Major depressive disorder","Bipolar I disorder","Bipolar II disorder","Schizoaffective disorder"],"steps":[{"kind":"single","label":"First impression","prompt":"A patient presents today with a major depressive episode. The chart documents a full manic episode ten years ago.","competency":"n2.longitudinal","choices":"Which longitudinal principle applies?","reveal":["Current diagnosis depends only on the present episode","A past manic episode remains structuring for longitudinal diagnosis","Old mania is irrelevant"],"ask_leader":true},{"kind":"multi","label":"Inquiry","prompt":"Which two checks are most important before integrating the old episode?","competency":"n2.evidence","choices":["Quality of documentation of the manic episode","Exclusion of induced/secondary causes at the time","Duration of current depression only","Patient''s current preferred label"],"required":2,"max":2},{"kind":"single","label":"New information","prompt":"The old chart describes one week of expansive mood, increased energy, marked impairment and no identified induced cause.","competency":"n2.longitudinal","choices":"Which longitudinal diagnosis gains strongly?","reveal":["Bipolar I disorder","Bipolar II disorder","Major depressive disorder"],"ask_leader":true},{"kind":"single","label":"Do you maintain?","prompt":"The current episode is purely depressive, with no manic symptoms.","competency":"n2.revision","choices":"Does this change the longitudinal diagnosis?","reveal":["Yes, it becomes major depressive disorder","No, the past manic episode remains decisive","Yes, it becomes bipolar II"],"ask_leader":true},{"kind":"single","label":"Decisive argument","prompt":"Which datum structures the lifetime diagnosis?","competency":"n2.discrimination","choices":["Today''s symptom","At least one authenticated manic episode","Number of depressive episodes"]},{"kind":"final","label":"Signature","prompt":"Which longitudinal diagnosis is best supported?","competency":"n2.formulation","diagnosis_choices":["Major depressive disorder","Bipolar I disorder","Bipolar II disorder","Schizoaffective disorder"],"argument_choices":["Current depression","Documented past mania","No current mania"]}],"references":["DSM-5-TR — Troubles bipolaires et apparentés","Jansson & Nordgaard — The Psychiatric Interview"]}}'::jsonb,'{"steps":[{"kind":"single","correct":1,"certainty_target":90,"leader_correct":[1]},{"kind":"multi","correct":[0,1],"certainty_target":90},{"kind":"single","correct":0,"certainty_target":95,"leader_correct":[1]},{"kind":"single","correct":1,"certainty_target":95,"leader_correct":[1],"revision":"maintain"},{"kind":"single","correct":1},{"kind":"final","diagnosis":1,"argument":1,"certainty_target":95}]}'::jsonb,100),
(12,'bipolar','{"fr":{"title":"Le bon doute","subtitle":"Savoir ne pas conclure trop tôt fait partie du raisonnement clinique.","intro":"Savoir ne pas conclure trop tôt fait partie du raisonnement clinique.","hypotheses":["Hypomanie certaine","Période d’activation possible, insuffisamment caractérisée","Manie certaine","Aucun antécédent pertinent"],"steps":[{"kind":"single","label":"Première impression","prompt":"Un patient se souvient d’une période ancienne où il « dormait moins et faisait beaucoup de choses », mais ne peut préciser ni durée, ni retentissement, ni changement observé par autrui.","competency":"n2.uncertainty","choices":"Quelle formulation est la plus rigoureuse ?","reveal":["Hypomanie certaine","Période d’activation possible, insuffisamment caractérisée","Manie certaine"],"ask_leader":true,"debrief":"Quand durée, retentissement et changement observable manquent, l’hypomanie ne peut pas être déclarée certaine.","discriminant":"Données insuffisantes pour franchir le seuil.","trap":"Un souvenir évocateur pousse à compléter mentalement les informations manquantes."},{"kind":"multi","label":"Enquête","prompt":"Quelles deux données manquantes auraient le plus de valeur pour reclasser cet antécédent ?","competency":"n2.evidence","choices":["Durée et caractère nettement délimité","Changement observable du fonctionnement / information collatérale","Couleur préférée à l’époque","Nombre de voyages réalisés"],"required":2,"max":2,"debrief":"Durée/délimitation et changement observable sont les données qui permettraient le mieux de reclasser l’antécédent.","discriminant":"Seuil temporel + baseline observable.","trap":"Les détails biographiques non reliés à la définition de l’épisode ont peu de valeur."},{"kind":"single","label":"Nouvelle donnée","prompt":"Aucun proche n’est disponible et le patient reste incertain sur la durée, mais se rappelle qu’il se sentait bien avec très peu de sommeil.","competency":"n2.uncertainty","choices":"Que pouvez-vous conclure ?","reveal":["Une hypomanie est désormais certaine","L’antécédent reste suggestif mais insuffisamment caractérisé","Il faut effacer l’information"],"ask_leader":true,"debrief":"Un souvenir de sommeil réduit sans autres données reste suggestif mais insuffisant.","discriminant":"Incomplétude de la caractérisation.","trap":"Une donnée typique peut sembler plus probante qu’elle ne l’est."},{"kind":"single","label":"Vous maintenez ?","prompt":"Le dossier ancien ne fournit aucune donnée supplémentaire.","competency":"n2.revision","choices":"Quelle attitude est la plus robuste ?","reveal":["Transformer l’incertitude en diagnostic pour ne pas perdre l’information","Conserver explicitement l’incertitude et poursuivre la reconstruction longitudinale","Considérer que rien n’a jamais eu lieu"],"ask_leader":true,"debrief":"La formulation doit préserver explicitement l’incertitude plutôt que la transformer artificiellement en certitude.","discriminant":"Incertitude documentée.","trap":"La pression de conclure peut mener à une fausse précision."},{"kind":"single","label":"Argument décisif","prompt":"Quelle compétence est testée ici ?","competency":"n2.discrimination","choices":["Reconnaître quand les données ne permettent pas de franchir un seuil diagnostique","Toujours choisir le diagnostic le plus probable","Éviter toute hypothèse provisoire"],"debrief":"La compétence centrale est de reconnaître quand les données n’autorisent pas un seuil diagnostique.","discriminant":"Calibration diagnostique.","trap":"Choisir coûte que coûte une étiquette n’est pas du raisonnement clinique."},{"kind":"final","label":"Signature","prompt":"Quelle formulation finale est la plus défendable ?","competency":"n2.formulation","diagnosis_choices":["Hypomanie certaine","Période d’activation possible, insuffisamment caractérisée","Manie certaine","Aucun antécédent pertinent"],"argument_choices":["Sommeil réduit seul","Données rétrospectives suggestives mais insuffisantes pour caractériser l’épisode","Absence de témoin"],"debrief":"La meilleure signature est une période d’activation possible, insuffisamment caractérisée.","discriminant":"Formulation proportionnée aux données.","trap":"L’incertitude bien formulée est préférable à une certitude non justifiée."}],"references":["Jansson & Nordgaard — The Psychiatric Interview","DSM-5-TR — Troubles bipolaires et apparentés"]},"en":{"title":"The right doubt","subtitle":"Knowing when not to conclude is part of clinical reasoning.","intro":"Knowing when not to conclude is part of clinical reasoning.","hypotheses":["Definite hypomania","Possible activation period, insufficiently characterized","Definite mania","No relevant history"],"steps":[{"kind":"single","label":"First impression","prompt":"A patient recalls an old period when he ''slept less and did many things'' but cannot specify duration, impairment, or observable change.","competency":"n2.uncertainty","choices":"What is the most rigorous formulation?","reveal":["Definite hypomania","Possible activation period, insufficiently characterized","Definite mania"],"ask_leader":true},{"kind":"multi","label":"Inquiry","prompt":"Which two missing data would be most valuable to reclassify this history?","competency":"n2.evidence","choices":["Duration and clear delimitation","Observable functional change / collateral information","Favorite color at the time","Number of trips taken"],"required":2,"max":2},{"kind":"single","label":"New information","prompt":"No collateral informant is available and the patient remains unsure about duration, but remembers feeling well on very little sleep.","competency":"n2.uncertainty","choices":"What can you conclude?","reveal":["Hypomania is now definite","The history remains suggestive but insufficiently characterized","The information should be deleted"],"ask_leader":true},{"kind":"single","label":"Do you maintain?","prompt":"The old chart provides no additional information.","competency":"n2.revision","choices":"What is the most robust approach?","reveal":["Convert uncertainty into diagnosis to preserve the information","Explicitly preserve uncertainty and continue longitudinal reconstruction","Assume nothing ever happened"],"ask_leader":true},{"kind":"single","label":"Decisive argument","prompt":"Which skill is being tested?","competency":"n2.discrimination","choices":["Recognizing when data do not justify crossing a diagnostic threshold","Always choosing the most likely diagnosis","Avoiding all provisional hypotheses"]},{"kind":"final","label":"Signature","prompt":"Which final formulation is most defensible?","competency":"n2.formulation","diagnosis_choices":["Definite hypomania","Possible activation period, insufficiently characterized","Definite mania","No relevant history"],"argument_choices":["Reduced sleep alone","Suggestive retrospective data insufficient to characterize the episode","No witness"]}],"references":["Jansson & Nordgaard — The Psychiatric Interview","DSM-5-TR — Troubles bipolaires et apparentés"]}}'::jsonb,'{"steps":[{"kind":"single","correct":1,"certainty_target":85,"leader_correct":[1]},{"kind":"multi","correct":[0,1],"certainty_target":90},{"kind":"single","correct":1,"certainty_target":90,"leader_correct":[1]},{"kind":"single","correct":1,"certainty_target":95,"leader_correct":[1],"revision":"maintain"},{"kind":"single","correct":0},{"kind":"final","diagnosis":1,"argument":1,"certainty_target":95}]}'::jsonb,100)
on conflict(template_id) do update set
 course_key=excluded.course_key,
 content=excluded.content,
 answer_key=excluded.answer_key,
 max_score=excluded.max_score;

-- Le défi courant tourne sur les templates disponibles, sans supposer que les IDs commencent à 1.
create or replace function public.get_current_challenge(p_course_key text default 'bipolar')
returns table(challenge_key text,starts_at timestamptz,ends_at timestamptz,content jsonb)
language plpgsql security definer set search_path=public as $$
declare
  v_count int;
  v_offset int;
  v_start timestamptz;
  v_content jsonb;
begin
  if auth.uid() is null then raise exception 'Authentication required'; end if;
  select count(*) into v_count from public.challenge_templates where course_key=p_course_key;
  if v_count=0 then return; end if;
  v_start:=date_trunc('week',now());
  v_offset:=(extract(week from v_start)::int % v_count);
  select ct.content into v_content
  from public.challenge_templates ct
  where ct.course_key=p_course_key
  order by ct.template_id
  offset v_offset limit 1;
  challenge_key:=p_course_key||'-'||to_char(v_start,'IYYY-IW');
  starts_at:=v_start;
  ends_at:=v_start+interval '7 days';
  content:=v_content;
  return next;
end;$$;
revoke all on function public.get_current_challenge(text) from public;
grant execute on function public.get_current_challenge(text) to authenticated;

-- Score /100 :
-- Décisions cliniques 30 · Recherche d'information 20 · Hiérarchisation 15
-- Flexibilité 15 · Argument discriminant 10 · Calibration 10.
drop function if exists public.submit_weekly_challenge(text,jsonb);
create function public.submit_weekly_challenge(p_challenge_key text,p_answers jsonb)
returns table(score integer,accepted boolean,breakdown jsonb)
language plpgsql security definer set search_path=public as $$
declare
  v_uid uuid:=auth.uid();
  v_start timestamptz:=date_trunc('week',now());
  v_expected_key text;
  v_count int; v_offset int; v_template_id int; v_key jsonb;
  v_existing integer; v_existing_breakdown jsonb;
  v_i integer; v_expected jsonb; v_answer jsonb; v_kind text;
  v_choice integer; v_conf integer; v_target integer; v_diff integer;
  v_selected jsonb; v_correct jsonb; v_overlap integer;
  v_leader integer; v_prev_leader integer:=null; v_revision_expected text;
  v_diag integer; v_arg integer;
  v_decisions integer:=0; v_search integer:=0; v_hierarchy integer:=0;
  v_flex integer:=0; v_argument integer:=0; v_calibration integer:=0;
  v_stage integer:=0; v_stages jsonb:='[]'::jsonb; v_result jsonb;
  v_core_ok boolean:=false;
begin
  if v_uid is null then raise exception 'Authentication required'; end if;
  select count(*) into v_count from public.challenge_templates where course_key='bipolar';
  if v_count=0 then raise exception 'No challenge template'; end if;
  v_offset:=(extract(week from v_start)::int % v_count);
  v_expected_key:='bipolar-'||to_char(v_start,'IYYY-IW');
  if p_challenge_key<>v_expected_key then raise exception 'Challenge is not current'; end if;

  select ct.template_id,ct.answer_key into v_template_id,v_key
  from public.challenge_templates ct
  where ct.course_key='bipolar'
  order by ct.template_id
  offset v_offset limit 1;

  if jsonb_typeof(p_answers)<>'array'
     or jsonb_array_length(p_answers)<>jsonb_array_length(v_key->'steps')
  then raise exception 'Incomplete challenge'; end if;

  select ca.score,ca.breakdown into v_existing,v_existing_breakdown
  from public.challenge_attempts ca
  where ca.user_id=v_uid and ca.challenge_key=p_challenge_key;

  if v_existing is not null then
    score:=v_existing; accepted:=false; breakdown:=coalesce(v_existing_breakdown,'{}'::jsonb);
    return next; return;
  end if;

  for v_i in 0..jsonb_array_length(v_key->'steps')-1 loop
    v_expected:=v_key->'steps'->v_i;
    v_answer:=p_answers->v_i;
    v_kind:=v_expected->>'kind';
    v_conf:=greatest(0,least(coalesce((v_answer->>'confidence')::int,70),100));
    v_leader:=coalesce((v_answer->>'leader')::int,-1);
    v_core_ok:=false;
    v_stage:=0;

    if v_i=0 and v_kind='single' then
      v_choice:=coalesce((v_answer->>'choice')::int,-1);
      v_core_ok:=v_choice=(v_expected->>'correct')::int;
      if v_core_ok then v_decisions:=v_decisions+8; v_stage:=v_stage+8; end if;
      if v_leader>=0 and exists(select 1 from jsonb_array_elements_text(coalesce(v_expected->'leader_correct','[]'::jsonb)) x where x.value::int=v_leader)
      then v_hierarchy:=v_hierarchy+5; v_stage:=v_stage+5; end if;
      v_prev_leader:=case when v_leader>=0 then v_leader else null end;

    elsif v_i=1 and v_kind='multi' then
      v_selected:=coalesce(v_answer->'selected','[]'::jsonb);
      v_correct:=coalesce(v_expected->'correct','[]'::jsonb);
      if jsonb_typeof(v_selected)<>'array' then raise exception 'Invalid multi answer'; end if;
      if v_selected @> v_correct and v_correct @> v_selected then
        v_search:=20; v_stage:=v_stage+20; v_core_ok:=true;
      else
        select count(*) into v_overlap
        from jsonb_array_elements_text(v_selected) s
        where exists(select 1 from jsonb_array_elements_text(v_correct) c where c.value=s.value);
        if v_overlap>0 then v_search:=10; v_stage:=v_stage+10; end if;
      end if;

    elsif v_i=2 and v_kind='single' then
      v_choice:=coalesce((v_answer->>'choice')::int,-1);
      v_core_ok:=v_choice=(v_expected->>'correct')::int;
      if v_core_ok then v_decisions:=v_decisions+8; v_stage:=v_stage+8; end if;
      if v_leader>=0 and exists(select 1 from jsonb_array_elements_text(coalesce(v_expected->'leader_correct','[]'::jsonb)) x where x.value::int=v_leader)
      then v_hierarchy:=v_hierarchy+5; v_stage:=v_stage+5; end if;
      v_prev_leader:=case when v_leader>=0 then v_leader else v_prev_leader end;

    elsif v_i=3 and v_kind='single' then
      v_choice:=coalesce((v_answer->>'choice')::int,-1);
      v_core_ok:=v_choice=(v_expected->>'correct')::int;
      if v_core_ok then v_flex:=v_flex+10; v_stage:=v_stage+10; end if;
      if v_leader>=0 and exists(select 1 from jsonb_array_elements_text(coalesce(v_expected->'leader_correct','[]'::jsonb)) x where x.value::int=v_leader)
      then v_hierarchy:=v_hierarchy+5; v_stage:=v_stage+5; end if;
      v_revision_expected:=coalesce(v_expected->>'revision','maintain');
      if v_prev_leader is not null and v_leader>=0 then
        if (v_revision_expected='change' and v_leader<>v_prev_leader)
           or (v_revision_expected='maintain' and v_leader=v_prev_leader)
        then v_flex:=v_flex+5; v_stage:=v_stage+5; end if;
      end if;
      v_prev_leader:=case when v_leader>=0 then v_leader else v_prev_leader end;

    elsif v_i=4 and v_kind='single' then
      v_choice:=coalesce((v_answer->>'choice')::int,-1);
      v_core_ok:=v_choice=(v_expected->>'correct')::int;
      if v_core_ok then v_argument:=10; v_stage:=v_stage+10; end if;

    elsif v_i=5 and v_kind='final' then
      v_diag:=coalesce((v_answer->>'diagnosis')::int,-1);
      v_arg:=coalesce((v_answer->>'argument')::int,-1);
      if v_diag=(v_expected->>'diagnosis')::int then v_decisions:=v_decisions+10; v_stage:=v_stage+10; end if;
      if v_arg=(v_expected->>'argument')::int then v_decisions:=v_decisions+4; v_stage:=v_stage+4; end if;
      v_core_ok:=v_diag=(v_expected->>'diagnosis')::int and v_arg=(v_expected->>'argument')::int;
    else
      raise exception 'Unsupported challenge step';
    end if;

    -- Calibration sur cinq moments : étapes 0,1,2,3 et signature.
    if v_i in (0,1,2,3,5) then
      v_target:=case when v_core_ok then coalesce((v_expected->>'certainty_target')::int,80) else 50 end;
      v_diff:=abs(v_conf-v_target);
      if v_diff<=10 then v_calibration:=v_calibration+2; v_stage:=v_stage+2;
      elsif v_diff<=25 then v_calibration:=v_calibration+1; v_stage:=v_stage+1;
      end if;
    end if;
    v_stages:=v_stages||jsonb_build_array(v_stage);
  end loop;

  v_decisions:=least(v_decisions,30);
  v_search:=least(v_search,20);
  v_hierarchy:=least(v_hierarchy,15);
  v_flex:=least(v_flex,15);
  v_argument:=least(v_argument,10);
  v_calibration:=least(v_calibration,10);

  score:=v_decisions+v_search+v_hierarchy+v_flex+v_argument+v_calibration;
  v_result:=jsonb_build_object(
    'dimensions',jsonb_build_object(
      'decisions',v_decisions,
      'information_search',v_search,
      'hierarchy',v_hierarchy,
      'flexibility',v_flex,
      'argument',v_argument,
      'calibration',v_calibration
    ),
    'stages',v_stages,
    'stage_max','[15,22,15,22,10,16]'::jsonb,
    'debrief_locked_until',v_start+interval '7 days',
    'template_id',v_template_id
  );

  insert into public.challenge_attempts(user_id,challenge_key,course_key,score,answers,breakdown)
  values(v_uid,p_challenge_key,'bipolar',score,p_answers,v_result);

  accepted:=true; breakdown:=v_result; return next;
end;$$;
revoke all on function public.submit_weekly_challenge(text,jsonb) from public;
grant execute on function public.submit_weekly_challenge(text,jsonb) to authenticated;

-- Le classement hebdomadaire autorise les ex æquo ; la vitesse n'intervient pas dans le rang.
create or replace function public.get_challenge_leaderboard(p_challenge_key text,p_limit integer default 20)
returns table(rank bigint,user_id uuid,display_name text,cohort_code text,score integer,submitted_at timestamptz)
language sql security definer set search_path=public as $$
with base as(
 select ca.user_id,p.display_name,p.cohort_code,ca.score,ca.submitted_at
 from public.challenge_attempts ca join public.profiles p on p.id=ca.user_id
 where ca.challenge_key=p_challenge_key
), ranked as(
 select rank() over(order by score desc) rank,* from base
)
select r.rank,r.user_id,r.display_name,r.cohort_code,r.score,r.submitted_at
from ranked r order by r.rank,r.display_name
limit greatest(1,least(coalesce(p_limit,20),100));
$$;
revoke all on function public.get_challenge_leaderboard(text,integer) from public;
grant execute on function public.get_challenge_leaderboard(text,integer) to authenticated;


-- Titulaire : meilleur score du défi de la semaine précédente. Les ex æquo restent ex æquo.
create or replace function public.get_coat_holder(p_course_key text default 'bipolar')
returns table(rank bigint,user_id uuid,display_name text,cohort_code text,score integer)
language sql security definer set search_path=public as $$
with k as(
 select p_course_key||'-'||to_char(date_trunc('week',now())-interval '7 days','IYYY-IW') challenge_key
), base as(
 select a.user_id,p.display_name,p.cohort_code,a.score
 from public.challenge_attempts a
 join public.profiles p on p.id=a.user_id,k
 where a.challenge_key=k.challenge_key
), ranked as(
 select rank() over(order by score desc) rank,* from base
)
select r.rank,r.user_id,r.display_name,r.cohort_code,r.score
from ranked r
where r.rank=1
order by r.display_name;
$$;
revoke all on function public.get_coat_holder(text) from public;
grant execute on function public.get_coat_holder(text) to authenticated;

-- Débrief du dernier défi clôturé auquel l'utilisateur a participé.
-- L'answer_key n'est exposée qu'après la clôture et uniquement à l'utilisateur concerné.
create or replace function public.get_my_latest_closed_challenge_debrief(p_course_key text default 'bipolar')
returns table(data jsonb)
language plpgsql security definer set search_path=public as $$
declare
  v_uid uuid:=auth.uid();
  v_week timestamptz:=date_trunc('week',now());
  v_attempt public.challenge_attempts%rowtype;
  v_tid integer;
  v_content jsonb;
  v_key jsonb;
begin
  if v_uid is null then raise exception 'Authentication required'; end if;
  select a.* into v_attempt
  from public.challenge_attempts a
  where a.user_id=v_uid
    and a.course_key=p_course_key
    and a.submitted_at < v_week
    and (a.breakdown ? 'template_id')
  order by a.submitted_at desc
  limit 1;
  if v_attempt.challenge_key is null then return; end if;
  v_tid:=coalesce((v_attempt.breakdown->>'template_id')::int,0);
  select ct.content,ct.answer_key into v_content,v_key
  from public.challenge_templates ct
  where ct.course_key=p_course_key and ct.template_id=v_tid;
  if v_content is null then return; end if;
  data:=jsonb_build_object(
    'challenge_key',v_attempt.challenge_key,
    'score',v_attempt.score,
    'answers',v_attempt.answers,
    'breakdown',v_attempt.breakdown,
    'content',v_content,
    'answer_key',v_key,
    'submitted_at',v_attempt.submitted_at
  );
  return next;
end;$$;
revoke all on function public.get_my_latest_closed_challenge_debrief(text) from public;
grant execute on function public.get_my_latest_closed_challenge_debrief(text) to authenticated;

-- V62 change le format classé (6 décisions + nouveau barème).
-- On réinitialise uniquement les tentatives de la semaine en cours pour éviter de mélanger les anciens scores avec le nouveau barème.
delete from public.challenge_attempts
where course_key='bipolar'
  and challenge_key='bipolar-'||to_char(date_trunc('week',now()),'IYYY-IW');
